8601	    async fn collect_sse_wire_tuples(resp: Response) -> Vec<(String, i64, String, String)> {
8602	        let bytes = axum::body::to_bytes(resp.into_body(), usize::MAX)
8603	            .await
8604	            .unwrap();
8605	        let body = String::from_utf8(bytes.to_vec()).unwrap();
8606	        let mut result = Vec::new();
8607	        for block in body.split("\n\n") {
8608	            let mut id: Option<String> = None;
8609	            let mut seq: Option<i64> = None;
8610	            let mut kind: Option<String> = None;
8611	            let mut phase: Option<String> = None;
8612	            for line in block.lines() {
8613	                if let Some(id_str) = line.strip_prefix("id:") {
8614	                    id = Some(id_str.trim().to_string());
8615	                } else if let Some(data_str) = line.strip_prefix("data:") {
8616	                    let trimmed = data_str.trim();
8617	                    if let Ok(v) = serde_json::from_str::<serde_json::Value>(trimmed) {
8618	                        seq = v.get("seq").and_then(|seq| seq.as_i64());
8619	                        kind = v
8620	                            .get("kind")
8621	                            .and_then(|kind| kind.as_str())
8622	                            .map(ToString::to_string);
8623	                        phase = v
8624	                            .get("phase")
8625	                            .and_then(|phase| phase.as_str())
8626	                            .map(ToString::to_string);
8627	                    }
8628	                }
8629	            }
8630	            if let (Some(id), Some(seq), Some(kind), Some(phase)) = (id, seq, kind, phase) {
8631	                assert_eq!(id, seq.to_string(), "SSE id line must equal data.seq");
8632	                result.push((id, seq, kind, phase));
8633	            }
8634	        }
8635	        result
8636	    }
